  if (game.cyanSigilPower.lt(0)) game.cyanSigilPower = new Decimal(0);
  g.rt.blueSigilPowerTemp = game.blueSigilPower.div(2);
  g.rt.SU4amountCanBuy = Decimal.affordGeometricSeries(g.rt.blueSigilPowerTemp, 1, 1.5, game.blueSigilUpgradesBought[0]);
  g.rt.SU4Cost = Decimal.sumGeometricSeries(g.rt.SU4amountCanBuy, 1, 1.5, game.blueSigilUpgradesBought[0]);
  if (game.blueSigilPower.lt("e1e10")) game.blueSigilPower = game.blueSigilPower.sub(g.rt.SU4Cost);
