  game.blueSigilUpgrade1Cost = new Decimal(1.5).pow(game.blueSigilUpgradesBought[0]).floor();
  g.rt.SU5amountCanBuy = Decimal.affordGeometricSeries(g.rt.blueSigilPowerTemp, 20, 1.5, game.blueSigilUpgradesBought[1]);
  g.rt.SU5Cost = Decimal.sumGeometricSeries(g.rt.SU5amountCanBuy, 20, 1.5, game.blueSigilUpgradesBought[1]);
  if (game.blueSigilPower.lt("e1e10")) game.blueSigilPower = game.blueSigilPower.sub(g.rt.SU5Cost);
